{"content":""""Robust meeting scheduler for Engineering, Design, and Product teams.

Searches Feb 5-9, 2024 (Mon-Fri) for the earliest valid 2-hour slot
satisfying all work-hour, lunch, buffer, and priority constraints.
All times handled in UTC.
"""

from datetime import datetime, timedelta, timezone, date, time


def _parse_ics_datetime(value: str) -> datetime:
    """Parse an ICS DATE-TIME value into an aware UTC datetime."""
    v = value.strip()
    # Strip trailing Z but remember it means UTC.
    is_utc = v.endswith("Z")
    if is_utc:
        v = v[:-1]
    # Remove any inline timezone artifacts (should already be split off).
    fmts = ("%Y%m%dT%H%M%S", "%Y%m%dT%H%M", "%Y%m%d")
    for fmt in fmts:
        try:
            dt = datetime.strptime(v, fmt)
            break
        except ValueError:
            continue
    else:
        # Try ISO-ish fallback: 2024-02-05T09:30:00
        iso = value.strip().replace("Z", "+00:00")
        try:
            dt = datetime.fromisoformat(iso)
            if dt.tzinfo is not None:
                return dt.astimezone(timezone.utc)
            return dt.replace(tzinfo=timezone.utc)
        except ValueError:
            raise ValueError(f"Unparseable ICS datetime: {value!r}")
    if dt.tzinfo is None:
        # Floating times are interpreted as UTC per task statement.
        dt = dt.replace(tzinfo=timezone.utc)
    else:
        dt = dt.astimezone(timezone.utc)
    # Date-only values parse to midnight UTC.
    return dt


def parse_ics_events(path: str):
    """Parse all VEVENT DTSTART/DTEND pairs from an ICS file.

    Returns a list of (start, end) aware UTC datetimes.
    """
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        raw_lines = f.read().splitlines()

    # Unfold folded lines (continuation starts with space or tab).
    lines = []
    for ln in raw_lines:
        if ln.startswith(" ") or ln.startswith("\t"):
            if lines:
                lines[-1] += ln[1:]
            continue
        lines.append(ln)

    events = []
    in_event = False
    dtstart = None
    dtend = None
    for ln in lines:
        line = ln.strip()
        if line == "BEGIN:VEVENT":
            in_event = True
            dtstart = None
            dtend = None
        elif line == "END:VEVENT":
            if in_event and dtstart is not None:
                if dtend is None:
                    # Default duration 1 hour when DTEND missing.
                    dtend = dtstart + timedelta(hours=1)
                if dtend < dtstart:
                    dtstart, dtend = dtend, dtstart
                events.append((dtstart, dtend))
            in_event = False
        elif in_event and (line.startswith("DTSTART") or line.startswith("DTEND")):
            # Split "DTSTART;TZID=...:value" -> value part after first colon.
            if ":" not in line:
                continue
            prop, val = line.split(":", 1)
            prop_name = prop.split(";")[0].strip().upper()
            try:
                dt = _parse_ics_datetime(val.strip())
            except ValueError:
                continue
            if prop_name == "DTSTART":
                dtstart = dt
            elif prop_name == "DTEND":
                dtend = dt
    return events


class MeetingScheduler:
    """Find the earliest valid 2-hour Project Kickoff Meeting slot."""

    DURATION = timedelta(minutes=120)
    PRODUCT_BUFFER = timedelta(minutes=20)

    def __init__(self):
        self.eng_events = []
        self.design_events = []
        self.prod_events = []
        self.slot_start = None
        self.slot_end = None

    def load_calendars(self, eng_path, design_path, prod_path):
        """Parse the three ICS files."""
        self.eng_events = parse_ics_events(eng_path)
        self.design_events = parse_ics_events(design_path)
        self.prod_events = parse_ics_events(prod_path)

    @staticmethod
    def _overlaps(s, e, a, b):
        # Half-open intervals: [s, e) overlaps [a, b) iff s < b and e > a.
        return s < b and e > a

    def _candidate_valid(self, s, e):
        day = s.date()
        # --- Per-team work hours (all UTC) ---
        # Engineering: 08:00 - 16:00
        if s < datetime.combine(day, time(8, 0), tzinfo=timezone.utc):
            return False
        if e > datetime.combine(day, time(16, 0), tzinfo=timezone.utc):
            return False
        # Design: 09:00 - 17:00
        if s < datetime.combine(day, time(9, 0), tzinfo=timezone.utc):
            return False
        if e > datetime.combine(day, time(17, 0), tzinfo=timezone.utc):
            return False
        # Product: 08:00 - 17:00 + morning block (no meeting before 09:00)
        if s < datetime.combine(day, time(9, 0), tzinfo=timezone.utc):
            return False
        if e > datetime.combine(day, time(17, 0), tzinfo=timezone.utc):
            return False

        # --- Lunch blocks (strictly unavailable) ---
        eng_lunch_s = datetime.combine(day, time(12, 0), tzinfo=timezone.utc)
        eng_lunch_e = datetime.combine(day, time(12, 30), tzinfo=timezone.utc)
        design_lunch_s = datetime.combine(day, time(12, 0), tzinfo=timezone.utc)
        design_lunch_e = datetime.combine(day, time(13, 0), tzinfo=timezone.utc)
        if self._overlaps(s, e, eng_lunch_s, eng_lunch_e):
            return False
        if self._overlaps(s, e, design_lunch_s, design_lunch_e):
            return False

        # --- Existing meetings (no overlap with any team) ---
        for a, b in self.eng_events:
            if self._overlaps(s, e, a, b):
                return False
        for a, b in self.design_events:
            if self._overlaps(s, e, a, b):
                return False
        for a, b in self.prod_events:
            if self._overlaps(s, e, a, b):
                return False

        # --- Product buffer: 20-min break immediately after any
        # existing product meeting before starting the new one.
        # i.e. start must be >= (product meeting end + 20 min)
        # for every product meeting that ended at or before start.
        for a, b in self.prod_events:
            if s >= b and s < b + self.PRODUCT_BUFFER:
                return False

        return True

    def find_slot(self):
        """Execute the search logic satisfying all constraints.

        Priority 1 (Tue, Wed, Thu) is searched chronologically first;
        Priority 2 (Mon, Fri) only if no Priority-1 slot exists.
        Search is minute-by-minute for the earliest valid start.
        Returns (start, end) aware UTC datetimes, or None if no slot.
        """
        days_p1 = [date(2024, 2, 6), date(2024, 2, 7), date(2024, 2, 8)]
        days_p2 = [date(2024, 2, 5), date(2024, 2, 9)]
        for day in days_p1 + days_p2:
            window_start = datetime.combine(day, time(9, 0), tzinfo=timezone.utc)
            latest_start = datetime.combine(day, time(16, 0), tzinfo=timezone.utc) - self.DURATION
            cur = window_start
            while cur <= latest_start:
                end = cur + self.DURATION
                if self._candidate_valid(cur, end):
                    self.slot_start = cur
                    self.slot_end = end
                    return (cur, end)
                cur += timedelta(minutes=1)
        self.slot_start = None
        self.slot_end = None
        return None

    def save_ics(self, output_path):
        """Generate the result file in RFC 5545 format."""
        if self.slot_start is None or self.slot_end is None:
            raise ValueError("No slot found: call find_slot() first and ensure it returns a slot.")
        fmt = "%Y%m%dT%H%M%SZ"
        dtstamp = datetime.now(timezone.utc).strftime(fmt)
        uid = "project-kickoff-meeting@meetingscheduler"
        content = (
            "BEGIN:VCALENDAR\r\n"
            "VERSION:2.0\r\n"
            "PRODID:-//MeetingScheduler//EN\r\n"
            "BEGIN:VEVENT\r\n"
            f"UID:{uid}\r\n"
            f"DTSTAMP:{dtstamp}\r\n"
            f"DTSTART:{self.slot_start.strftime(fmt)}\r\n"
            f"DTEND:{self.slot_end.strftime(fmt)}\r\n"
            "SUMMARY:Project Kickoff Meeting\r\n"
            "END:VEVENT\r\n"
            "END:VCALENDAR\r\n"
        )
        with open(output_path, "w", encoding="utf-8", newline="") as f:
            f.write(content)


def _default_paths():
    import os
    base = "/app"
    cands = [
        (os.path.join(base, "engineering_calendar.ics"),
         os.path.join(base, "design_calendar.ics"),
         os.path.join(base, "product_calendar.ics")),
        ("engineering_calendar.ics",
         "design_calendar.ics",
         "product_calendar.ics"),
    ]
    for triple in cands:
        if all(os.path.exists(p) for p in triple):
            return triple
    return cands[0]


if __name__ == "__main__":
    import os
    eng, des, prod = _default_paths()
    scheduler = MeetingScheduler()
    scheduler.load_calendars(eng, des, prod)
    slot = scheduler.find_slot()
    if slot is None:
        raise SystemExit("No valid slot found between Feb 5-9, 2024.")
    print(f"Scheduled: {slot[0].isoformat()} -> {slot[1].isoformat()}")
    out = "/app/meeting_scheduled.ics"
    scheduler.save_ics(out)
    print(f"Saved to {out}")
